{"file_path":"src/uri.js","content":"/**
 * URI reference parsing, normalization and reference resolution
 * following RFC 3986's generic syntax.
 */

/** Thrown for record-level failures; `message` is the text after `error: line N: `. */
export class UriError extends Error {}

const REFERENCE = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#(.*))?$/

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

const HEX = /^[0-9A-Fa-f]{2}$/

/**
 * Split a URI reference into its five generic components. An absent
 * component is `undefined`; an empty one is the empty string.
 */
export function parse(reference) {
  const match = REFERENCE.exec(reference)
  const [, scheme, authority, path, query, fragment] = match
  return { scheme, authority, path, query, fragment }
}

/**
 * Split an authority into userinfo, host and port. The userinfo is what
 * precedes the last `@`; the port is what follows the first `:` after the
 * last `]`.
 */
export function parseAuthority(authority) {
  let userinfo
  let rest = authority
  const at = authority.lastIndexOf('@')
  if (at !== -1) {
    userinfo = authority.slice(0, at)
    rest = authority.slice(at + 1)
  }
  let host = rest
  let port
  const bracket = rest.lastIndexOf(']')
  const colon = rest.indexOf(':', bracket + 1)
  if (colon !== -1) {
    host = rest.slice(0, colon)
    port = rest.slice(colon + 1)
  }
  return { userinfo, host, port }
}

function formatAuthority({ userinfo, host, port }) {
  let out = ''
  if (userinfo !== undefined) out += userinfo + '@'
  out += host
  if (port !== undefined) out += ':' + port
  return out
}

/** Reassemble the components of a URI reference (RFC 3986 section 5.3). */
export function format({ scheme, authority, path, query, fragment }) {
  let out = ''
  if (scheme !== undefined) out += scheme + ':'
  if (authority !== undefined) out += '//' + authority
  out += path
  if (query !== undefined) out += '?' + query
  if (fragment !== undefined) out += '#' + fragment
  return out
}

function isUnreserved(code) {
  return (
    (code >= 0x41 && code <= 0x5a) ||
    (code >= 0x61 && code <= 0x7a) ||
    (code >= 0x30 && code <= 0x39) ||
    code === 0x2d ||
    code === 0x2e ||
    code === 0x5f ||
    code === 0x7e
  )
}

function checkPercentEncodings(text, component) {
  for (let i = 0; i < text.length; i++) {
    if (text[i] !== '%') continue
    if (!HEX.test(text.slice(i + 1, i + 3))) {
      throw new UriError(`the ${component} has a truncated percent-encoding`)
    }
    i += 2
  }
}

/** Uppercase every `%XX` and decode the ones that stand for unreserved characters. */
function normalizePercentEncodings(text) {
  let out = ''
  for (let i = 0; i < text.length; i++) {
    if (text[i] !== '%') {
      out += text[i]
      continue
    }
    const digits = text.slice(i + 1, i + 3).toUpperCase()
    const code = parseInt(digits, 16)
    out += isUnreserved(code) ? String.fromCharCode(code) : '%' + digits
    i += 2
  }
  return out
}

function lowerAscii(text) {
  let out = ''
  for (const character of text) {
    const code = character.charCodeAt(0)
    out += code >= 0x41 && code <= 0x5a ? String.fromCharCode(code + 0x20) : character
  }
  return out
}

/**
 * Report a truncated percent-encoding in any component, checking the path,
 * the userinfo, the host, the query and the fragment in that order.
 */
export function checkComponents(parts) {
  checkPercentEncodings(parts.path, 'path')
  const authority = parts.authority === undefined ? undefined : parseAuthority(parts.authority)
  if (authority && authority.userinfo !== undefined) {
    checkPercentEncodings(authority.userinfo, 'userinfo')
  }
  if (authority) checkPercentEncodings(authority.host, 'host')
  if (parts.query !== undefined) checkPercentEncodings(parts.query, 'query')
  if (parts.fragment !== undefined) checkPercentEncodings(parts.fragment, 'fragment')
}

/** Remove dot segments from a path (RFC 3986 section 5.2.4). */
export function removeDotSegments(path) {
  let input = path
  const output = []
  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      output.pop()
    } else if (input === '/..') {
      input = '/'
      output.pop()
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      let end = input.indexOf('/', input.startsWith('/') ? 1 : 0)
      if (end === -1) end = input.length
      output.push(input.slice(0, end))
      input = input.slice(end)
    }
  }
  return output.join('')
}

/** Normalize the components of a URI reference in place, returning new ones. */
export function normalizeParts(parts) {
  let { scheme, authority, path, query, fragment } = parts
  if (scheme !== undefined) scheme = lowerAscii(scheme)

  if (authority !== undefined) {
    const { userinfo, host, port } = parseAuthority(authority)
    const normalized = {
      userinfo: userinfo === undefined ? undefined : normalizePercentEncodings(userinfo),
      host: lowerAscii(normalizePercentEncodings(host)),
      port,
    }
    if (port !== undefined) {
      const isDefault = scheme !== undefined && DEFAULT_PORTS[scheme] === port
      if (port === '' || isDefault) normalized.port = undefined
    }
    authority = formatAuthority(normalized)
  }

  path = removeDotSegments(normalizePercentEncodings(path))
  if (query !== undefined) query = normalizePercentEncodings(query)
  if (fragment !== undefined) fragment = normalizePercentEncodings(fragment)
  if (authority !== undefined && path === '') path = '/'

  return { scheme, authority, path, query, fragment }
}

/** Normalize a URI reference given as text. */
export function normalize(reference) {
  const parts = parse(reference)
  checkComponents(parts)
  return format(normalizeParts(parts))
}

function merge(base, referencePath) {
  if (base.authority !== undefined && base.path === '') return '/' + referencePath
  const slash = base.path.lastIndexOf('/')
  if (slash === -1) return referencePath
  return base.path.slice(0, slash + 1) + referencePath
}

/** Resolve a reference against a base (RFC 3986 section 5.2.2, strict). */
export function resolveParts(base, reference) {
  if (reference.scheme !== undefined) {
    return {
      scheme: reference.scheme,
      authority: reference.authority,
      path: removeDotSegments(reference.path),
      query: reference.query,
      fragment: reference.fragment,
    }
  }
  if (reference.authority !== undefined) {
    return {
      scheme: base.scheme,
      authority: reference.authority,
      path: removeDotSegments(reference.path),
      query: reference.query,
      fragment: reference.fragment,
    }
  }
  if (reference.path === '') {
    return {
      scheme: base.scheme,
      authority: base.authority,
      path: base.path,
      query: reference.query === undefined ? base.query : reference.query,
      fragment: reference.fragment,
    }
  }
  const path = reference.path.startsWith('/')
    ? removeDotSegments(reference.path)
    : removeDotSegments(merge(base, reference.path))
  return {
    scheme: base.scheme,
    authority: base.authority,
    path,
    query: reference.query,
    fragment: reference.fragment,
  }
}

/** Resolve a reference against a base URI and normalize the result. */
export function resolve(baseText, referenceText) {
  const base = parse(baseText)
  if (base.scheme === undefined) throw new UriError('the base has no scheme')
  checkComponents(base)
  const reference = parse(referenceText)
  checkComponents(reference)
  return format(normalizeParts(resolveParts(base, reference)))
}
"}

