{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { readFileSync } from 'node:fs'
import { UriError, normalize, resolve } from './uri.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

/** Split the input into records, dropping the empty tail of a trailing newline. */
function records(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function main() {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || (argv[0] !== 'normalize' && argv[0] !== 'resolve')) {
    fail('usage: cli.js normalize|resolve')
  }
  const mode = argv[0]
  const lines = records(readStdin())
  const output = []
  for (let index = 0; index < lines.length; index++) {
    const record = lines[index]
    try {
      if (mode === 'normalize') {
        output.push(normalize(record))
      } else {
        const space = record.indexOf(' ')
        if (space === -1) throw new UriError('expected a base and a reference')
        output.push(resolve(record.slice(0, space), record.slice(space + 1)))
      }
    } catch (error) {
      if (error instanceof UriError) fail(`line ${index + 1}: ${error.message}`)
      throw error
    }
  }
  process.stdout.write(output.map((line) => line + '\n').join(''))
}

main()
"}

