{"file_path":"src/uri.js","content":"/**
 * URI reference parsing, normalization and reference resolution per RFC 3986.
 */

export class UriError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

const DEFAULT_PORTS = {
  http: '80',
  ws: '80',
  https: '443',
  wss: '443',
  ftp: '21',
}

function isHexDigit(ch) {
  return (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F')
}

function isUnreserved(code) {
  return (
    (code >= 0x41 && code <= 0x5a) ||
    (code >= 0x61 && code <= 0x7a) ||
    (code >= 0x30 && code <= 0x39) ||
    code === 0x2d ||
    code === 0x2e ||
    code === 0x5f ||
    code === 0x7e
  )
}

function asciiLower(text) {
  let out = ''
  for (const ch of text) {
    const code = ch.charCodeAt(0)
    out += code >= 0x41 && code <= 0x5a ? String.fromCharCode(code + 32) : ch
  }
  return out
}

/** Parses a URI reference by the generic syntax. Absent components are null. */
export function parse(text) {
  let scheme = null
  let rest = text
  for (let i = 0; i < text.length; i += 1) {
    const ch = text[i]
    if (ch === '/' || ch === '?' || ch === '#') break
    if (ch === ':') {
      scheme = text.slice(0, i)
      rest = text.slice(i + 1)
      break
    }
  }

  let authority = null
  if (rest.startsWith('//')) {
    const body = rest.slice(2)
    let end = body.length
    for (let i = 0; i < body.length; i += 1) {
      const ch = body[i]
      if (ch === '/' || ch === '?' || ch === '#') {
        end = i
        break
      }
    }
    authority = body.slice(0, end)
    rest = body.slice(end)
  }

  let fragment = null
  const hash = rest.indexOf('#')
  if (hash !== -1) {
    fragment = rest.slice(hash + 1)
    rest = rest.slice(0, hash)
  }

  let query = null
  const mark = rest.indexOf('?')
  if (mark !== -1) {
    query = rest.slice(mark + 1)
    rest = rest.slice(0, mark)
  }

  return { scheme, authority, path: rest, query, fragment }
}

/** Splits an authority into userinfo, host and port; absent parts are null. */
export function parseAuthority(authority) {
  let userinfo = null
  let rest = authority
  const at = authority.lastIndexOf('@')
  if (at !== -1) {
    userinfo = authority.slice(0, at)
    rest = authority.slice(at + 1)
  }

  let host = rest
  let port = null
  const bracket = rest.lastIndexOf(']')
  const colon = rest.indexOf(':', bracket === -1 ? 0 : bracket + 1)
  if (colon !== -1) {
    host = rest.slice(0, colon)
    port = rest.slice(colon + 1)
  }

  return { userinfo, host, port }
}

function buildAuthority({ userinfo, host, port }) {
  let out = ''
  if (userinfo !== null) out += `${userinfo}@`
  out += host
  if (port !== null) out += `:${port}`
  return out
}

/** Uppercases hex digits of percent triplets and decodes unreserved ones. */
export function normalizePercent(text, component) {
  let out = ''
  for (let i = 0; i < text.length; i += 1) {
    const ch = text[i]
    if (ch !== '%') {
      out += ch
      continue
    }
    const a = text[i + 1]
    const b = text[i + 2]
    if (a === undefined || b === undefined || !isHexDigit(a) || !isHexDigit(b)) {
      throw new UriError(component)
    }
    const code = parseInt(a + b, 16)
    if (isUnreserved(code)) {
      out += String.fromCharCode(code)
    } else {
      out += `%${(a + b).toUpperCase()}`
    }
    i += 2
  }
  return out
}

/** Removes dot segments from a path per RFC 3986 section 5.2.4. */
export function removeDotSegments(path) {
  let input = path
  const output = []
  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = `/${input.slice(3)}`
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = `/${input.slice(4)}`
      output.pop()
    } else if (input === '/..') {
      input = '/'
      output.pop()
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      let end = input.startsWith('/') ? input.indexOf('/', 1) : input.indexOf('/')
      if (end === -1) end = input.length
      output.push(input.slice(0, end))
      input = input.slice(end)
    }
  }
