function sortedStringify(obj, indent, depth = 0) {
  if (obj === null) {
    return 'null'
  }

  if (typeof obj === 'string') {
    return JSON.stringify(obj)
  }

  if (typeof obj === 'number' || typeof obj === 'boolean') {
    return JSON.stringify(obj)
  }

  if (Array.isArray(obj)) {
    if (obj.length === 0) {
      return '[]'
    }
    const items = obj.map(item => sortedStringify(item, indent, depth + 1))
    const indentStr = ' '.repeat((depth + 1) * indent)
    const closeIndentStr = ' '.repeat(depth * indent)
    return '[\n' + items.map(item => indentStr + item).join(',\n') + '\n' + closeIndentStr + ']'
  }

  if (typeof obj === 'object') {
    const keys = Object.keys(obj).sort()
    if (keys.length === 0) {
      return '{}'
    }
    const indentStr = ' '.repeat((depth + 1) * indent)
    const closeIndentStr = ' '.repeat(depth * indent)
    const items = keys.map(key => {
      const value = sortedStringify(obj[key], indent, depth + 1)
      return indentStr + JSON.stringify(key) + ': ' + value
    })
    return '{\n' + items.join(',\n') + '\n' + closeIndentStr + '}'
  }

  return JSON.stringify(obj)
}"}

