{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { readFileSync } from 'node:fs'
import { ParseError, parseElection } from './parse.js'
import { runElection } from './count.js'

const MODES = new Set(['rounds', 'tally'])

function die(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function report(mode, result) {
  const lines = []

  if (mode === 'rounds') {
    result.rounds.forEach((round, index) => {
      const parts = round.order.map((name) => `${name}=${round.counts.get(name)}`)
      parts.push(`exhausted=${round.exhausted}`)
      lines.push(`round ${index + 1}: ${parts.join(' ')}`)
      if (round.eliminated !== null) lines.push(`eliminated ${round.eliminated}`)
    })
  } else {
    lines.push(`rounds ${result.rounds.length}`)
  }

  lines.push(result.winner === null ? 'no winner' : `winner ${result.winner}`)
  return lines.map((line) => `${line}\n`).join('')
}

function main(argv) {
  if (argv.length !== 1 || !MODES.has(argv[0])) die('usage: cli.js rounds|tally')

  let election
  try {
    election = parseElection(readStdin())
  } catch (error) {
    if (error instanceof ParseError) die(error.message)
    throw error
  }

  process.stdout.write(report(argv[0], runElection(election)))
}

main(process.argv.slice(2))
"}

