{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { readFileSync } from 'node:fs'
import { parseGraph } from './parse.js'
import { findCycle, timings, priorities } from './schedule.js'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'

function fail(message, code) {
  process.stderr.write(message + '\n')
  process.exit(code)
}

function byName(a, b) {
  return a < b ? -1 : a > b ? 1 : 0
}

const argv = process.argv.slice(2)
const mode = argv[0]

let workers = 0
if ((mode === 'waves' || mode === 'explain') && argv.length === 1) {
  // fine
} else if (mode === 'pack' && argv.length === 2) {
  const raw = argv[1]
  if (!/^[1-9][0-9]*$/.test(raw)) fail('error: workers must be a positive integer', 2)
  workers = Number(raw)
} else {
  fail(USAGE, 2)
}

let input = ''
try {
  input = readFileSync(0, 'utf8')
} catch {
  input = ''
}

const graph = parseGraph(input, fail)
const { names, cost, deps } = graph

const cycle = findCycle(names, deps)
if (cycle) fail('error: cycle: ' + cycle.join(' -> '), 3)

const { start, finish, depth, total } = timings(names, cost, deps)
const sorted = names.slice().sort(byName)
const out = []

if (mode === 'waves') {
  let maxDepth = -1
  for (const n of names) if (depth.get(n) > maxDepth) maxDepth = depth.get(n)
  for (let k = 0; k <= maxDepth; k++) {
    const wave = sorted.filter((n) => depth.get(n) === k)
    out.push(`wave ${k}: ${wave.join(' ')}`)
  }
  out.push(`total ${total}`)
} else if (mode === 'explain') {
  for (const n of sorted) {
    out.push(`${n} start=${start.get(n)} finish=${finish.get(n)} depth=${depth.get(n)}`)
  }
  out.push(`total ${total}`)
} else {
  const prio = priorities(names, cost, deps)
  const lanes = []
  const freeAt = []
  for (let i = 0; i < workers; i++) {
    lanes.push([])
    freeAt.push(0)
  }
  const done = new Map() // name -> finish time
  let now = 0
  let makespan = 0

  const ready = (n) => {
    for (const d of deps.get(n)) {
      if (!done.has(d) || done.get(d) > now) return false
    }
    return true
  }

  while (done.size < names.length) {
    // pick the single best ready task startable at this instant
    let worker = -1
    for (let i = 0; i < workers; i++) {
      if (freeAt[i] <= now) {
        worker = i
        break
      }
    }
    let choice = null
    if (worker !== -1) {
      for (const n of sorted) {
        if (done.has(n) || !ready(n)) continue
        if (choice === null || prio.get(n) > prio.get(choice)) choice = n
      }
    }
    if (choice !== null) {
      const f = now + cost.get(choice)
      lanes[worker].push(`${choice}@${now}-${f}`)
      freeAt[worker] = f
      done.set(choice, f)
      if (f > makespan) makespan = f
      continue
    }
    // advance to the next instant a worker becomes free
    let next = Infinity
    for (let i = 0; i < workers; i++) {
      if (freeAt[i] > now && freeAt[i] < next) next = freeAt[i]
    }
    if (next === Infinity) break
    now = next
  }

  for (let i = 0; i < workers; i++) {
    out.push(lanes[i].length ? `worker ${i}: ${lanes[i].join(' ')}` : `worker ${i}:`)
  }
  out.push(`makespan ${makespan}`)
}

process.stdout.write(out.map((line) => line + '\n').join(''))
"}

{"file_path":"src/parse.js","content":"/** Reading the build graph out of the input text. */

const NAME = /^[A-Za-z0-9_.-]+$/
const COST = /^[0-9]+$/

/**
 * Parse the input into { names, cost, deps }. `fail(message, code)` reports
 * the first failure and does not return.
 */
export function parseGraph(input, fail) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cost = new Map()
  const deps = new Map() // name -> Set of dependency names
  const names = []
  const used = [] // every name a dep line mentions, in input order

  const edge = (from, to) => {
    let set = deps.get(from)
    if (!set) {
      set = new Set()
      deps.set(from, set)
    }
    set.add(to)
  }

  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const text = lines[i].trim()
    if (text === '' || text.startsWith('#')) continue
    const words = text.split(/\s+/)

    if (words[0] === 'task') {
      if (words.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`, 2)
      const name = words[1]
      if (!NAME.test(name)) fail(`error: line ${n}: invalid task name ${name}`, 2)
      if (!COST.test(words[2])) fail(`error: line ${n}: cost must be a non-negative integer`, 2)
      if (cost.has(name)) fail(`error: line ${n}: task ${name} is declared twice`, 2)
      cost.set(name, Number(words[2]))
      names.push(name)
      if (!deps.has(name)) deps.set(name, new Set())
    } else if (words[0] === 'dep') {
      if (words.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`, 2)
      for (let w = 1; w < words.length; w++) {
        if (!NAME.test(words[w])) fail(`error: line ${n}: invalid task name ${words[w]}`, 2)
        used.push(words[w])
      }
      for (let w = 2; w < words.length; w++) edge(words[1], words[w])
    } else {
      fail(`error: line ${n}: unknown directive ${words[0]}`, 2)
    }
  }

  for (const name of used) {
    if (!cost.has(name)) fail(`error: unknown task ${name}`, 2)
  }

  for (const name of names) if (!deps.has(name)) deps.set(name, new Set())

  return { names, cost, deps }
}
"}

