{"file_path":"src/cli.js","content":"#!/usr/bin/env node

import { readFileSync } from 'fs'

function readStdin() {
  try {
    return readFileSync(0, 'utf-8')
  } catch {
    return ''
  }
}

class ParseError extends Error {
  constructor(lineNum, message) {
    if (lineNum === null) {
      super(`error: ${message}`)
    } else {
      super(`error: line ${lineNum}: ${message}`)
    }
    this.lineNum = lineNum
  }
}

function parseInput(input) {
  const lines = input.split('\n')

  const ballots = []
  let candidates = null
  let lineNum = 0
  let ballotsDeclared = false

  for (const line of lines) {
    lineNum++

    // Skip empty lines
    if (!line.trim()) continue

    // Skip comments
    if (line.trim().startsWith('#')) continue

    const parts = line.trim().split(/\s+/)
    const directive = parts[0]

    if (directive === 'candidates') {
      if (candidates !== null || ballotsDeclared) {
        throw new ParseError(lineNum, 'candidates must be declared once, before any ballot')
      }

      if (parts.length < 2) {
        throw new ParseError(lineNum, 'expected candidates <name>...')
      }

      candidates = parts.slice(1)

      // Validate candidate names
      for (const name of candidates) {
        if (!/^[a-zA-Z0-9_-]+$/.test(name)) {
          throw new ParseError(lineNum, `invalid candidate name ${name}`)
        }
      }

      // Check for duplicates
      const seen = new Set()
      for (const name of candidates) {
        if (seen.has(name)) {
          throw new ParseError(lineNum, `candidate ${name} is declared twice`)
        }
        seen.add(name)
      }
    } else if (directive === 'ballot') {
      if (candidates === null) {
        throw new ParseError(lineNum, 'candidates must be declared once, before any ballot')
      }
      ballotsDeclared = true

      if (parts.length < 2) {
        throw new ParseError(lineNum, 'expected ballot <count> <candidate>...')
      }

      const countStr = parts[1]
      const count = parseInt(countStr, 10)

      // Validate count: must be positive integer, no leading zero
      if (isNaN(count) || count < 1 || countStr !== String(count)) {
        throw new ParseError(lineNum, 'count must be a positive integer')
      }

      const ranked = parts.slice(2)

      if (ranked.length === 0) {
        throw new ParseError(lineNum, 'expected ballot <count> <candidate>...')
      }

      // Validate candidates exist
      const candidateSet = new Set(candidates)
      for (const name of ranked) {
        if (!candidateSet.has(name)) {
          throw new ParseError(lineNum, `unknown candidate ${name}`)
        }
      }

      // Check for duplicates in ballot
      const seen = new Set()
      for (const name of ranked) {
        if (seen.has(name)) {
          throw new ParseError(lineNum, `candidate ${name} is repeated`)
        }
        seen.add(name)
      }

      ballots.push({ count, ranked })
    } else {
      throw new ParseError(lineNum, `unknown directive ${directive}`)
    }
  }

  if (candidates === null) {
    throw new ParseError(null, 'no candidates')
  }

  return { candidates, ballots }
}

function runElection(election) {
  const { candidates, ballots } = election
  const rounds = []
  let continuing = new Set(candidates)

  while (true) {
    // Count votes for this round
    const votes = {}
    for (const candidate of continuing) {
      votes[candidate] = 0
    }

    let exhausted = 0
    for (const ballot of ballots) {
      let voted = false
      for (const candidate of ballot.ranked) {
        if (continuing.has(candidate)) {
          votes[candidate] += ballot.count
          voted = true
          break
        }
      }
      if (!voted) {
        exhausted += ballot.count
      }
    }

    const activeTotal = Object.values(votes).reduce((a, b) => a + b, 0)

    // Record this round
    rounds.push({ votes: { ...votes }, exhausted, continuing: new Set(continuing) })

    // Check for winner
    for (const candidate of continuing) {
      if (votes[candidate] * 2 > activeTotal) {
        return { candidates, ballots, rounds, winner: candidate }
      }
    }

    // Check for no winner
    if (activeTotal === 0) {
      return { candidates, ballots, rounds, winner: null }
    }

    // Find candidate to eliminate
    const toEliminate = findToEliminate(continuing, rounds)
    continuing.delete(toEliminate)
  }
}

function findToEliminate(continuing, rounds) {
  function doTiebreak(candidates) {
    const currentRound = rounds[rounds.length - 1]
    const currentVotes = currentRound.votes

    // Find minimum votes in current round
    let minVotes = Math.min(...candidates.map(c => currentVotes[c]))
    let tied = candidates.filter(c => currentVotes[c] === minVotes)

    if (tied.length === 1) {
      return tied[0]
    }

    // Try to break tie by looking at all previous rounds
    for (let roundIdx = 0; roundIdx < rounds.length; roundIdx++) {
      const roundVotes = rounds[roundIdx].votes

      // Get votes for tied candidates in this round
      const votes = tied.map(c => roundVotes[c])
      const minRoundVotes = Math.min(...votes)
      const maxRoundVotes = Math.max(...votes)

      // Check if they all have equal votes in this round
      if (minRoundVotes < maxRoundVotes) {
        // Not all equal, keep only those with fewest and recurse
        const newTied = tied.filter(c => roundVotes[c] === minRoundVotes)
        return doTiebreak(newTied)
      }
    }

    // No round separates them, sort by name and eliminate last
    tied.sort((a, b) => b.localeCompare(a))
    return tied[0]
  }

  return doTiebreak(Array.from(continuing))
}

function printRounds(results) {
  const { rounds, winner } = results

  for (let i = 0; i < rounds.length; i++) {
    const round = rounds[i]
    const votes = round.votes
    const candidates = Array.from(round.continuing)

    // Sort by descending votes, then ascending name
    candidates.sort((a, b) => {
      if (votes[b] !== votes[a]) {
        return votes[b] - votes[a]
      }
      return a.localeCompare(b)
    })

    const voteStrs = candidates.map(c => `${c}=${votes[c]}`)
    process.stdout.write(`round ${i + 1}: ${voteStrs.join(' ')} exhausted=${round.exhausted}\n`)

    // Check if someone was eliminated
    if (i < rounds.length - 1) {
      const nextContinuing = rounds[i + 1].continuing

      for (const c of round.continuing) {
        if (!nextContinuing.has(c)) {
          process.stdout.write(`eliminated ${c}\n`)
          break
        }
      }
    }
  }

  if (winner) {
    process.stdout.write(`winner ${winner}\n`)
  } else {
    process.stdout.write('no winner\n')
  }
}

function printTally(results) {
  const { rounds, winner } = results

  process.stdout.write(`rounds ${rounds.length}\n`)
  if (winner) {
    process.stdout.write(`winner ${winner}\n`)
  } else {
    process.stdout.write('no winner\n')
  }
}

async function main() {
  const args = process.argv.slice(2)

  // Validate arguments
  if (args.length !== 1 || !['rounds', 'tally'].includes(args[0])) {
    process.stderr.write('error: usage: cli.js rounds|tally\n')
    process.exit(2)
  }

  const mode = args[0]
  const input = readStdin()

  try {
    const election = parseInput(input)
    const results = runElection(election)

    if (mode === 'rounds') {
      printRounds(results)
    } else {
      printTally(results)
    }

    process.exit(0)
  } catch (error) {
    process.stderr.write(error.message + '\n')
    process.exit(2)
  }
}

main().catch(error => {
  process.stderr.write(error.message + '\n')
  process.exit(2)
})
"}

