function findToEliminate(continuing, rounds) {
  function doTiebreak(candidates) {
    const currentRound = rounds[rounds.length - 1]
    const currentVotes = currentRound.votes

    // Find minimum votes in current round
    let minVotes = Math.min(...candidates.map(c => currentVotes[c]))
    let tied = candidates.filter(c => currentVotes[c] === minVotes)

    if (tied.length === 1) {
      return tied[0]
    }

    // Try to break tie by looking at all previous rounds
    for (let roundIdx = 0; roundIdx < rounds.length; roundIdx++) {
      const roundVotes = rounds[roundIdx].votes

      // Get votes for tied candidates in this round
      const votes = tied.map(c => roundVotes[c])
      const minRoundVotes = Math.min(...votes)
      const maxRoundVotes = Math.max(...votes)

      // Check if they all have equal votes in this round
      if (minRoundVotes < maxRoundVotes) {
