        const newTied = tied.filter(c => roundVotes[c] === minRoundVotes)
        return doTiebreak(newTied)
      }
    }

    // No round separates them, sort by name and eliminate last
    tied.sort((a, b) => b.localeCompare(a))
    return tied[0]
  }

  return doTiebreak(Array.from(continuing))
}

function printRounds(results) {
  const { rounds, winner } = results

  for (let i = 0; i < rounds.length; i++) {
    const round = rounds[i]
    const votes = round.votes
    const candidates = Array.from(round.continuing)

