        }
      }
    }
  }

  if (winner) {
    process.stdout.write(`winner ${winner}\n`)
  } else {
    process.stdout.write('no winner\n')
  }
}

function printTally(results) {
  const { rounds, winner } = results

  process.stdout.write(`rounds ${rounds.length}\n`)
  if (winner) {
    process.stdout.write(`winner ${winner}\n`)
  } else {
    process.stdout.write('no winner\n')
  }
}

async function main() {
  const args = process.argv.slice(2)

  // Validate arguments
  if (args.length !== 1 || !['rounds', 'tally'].includes(args[0])) {
    process.stderr.write('error: usage: cli.js rounds|tally\n')
    process.exit(2)
  }

  const mode = args[0]
  const input = readStdin()

  try {
    const election = parseInput(input)
    const results = runElection(election)

    if (mode === 'rounds') {
      printRounds(results)
    } else {
      printTally(results)
    }

    process.exit(0)
  } catch (error) {
    process.stderr.write(error.message + '\n')
    process.exit(2)
  }
}

