 * The parser for the configuration document. Every directive fits on one line,
 * so each line is scanned on its own by a small recursive descent parser.
 *
 * A value is one of these nodes:
 *   { kind: 'table',   map: Map<string, node>, header: boolean }
 *   { kind: 'array',   items: node[], aot: boolean }
 *   { kind: 'string',  value: string }
 *   { kind: 'integer', value: number }
 *   { kind: 'float',   value: number }
 *   { kind: 'boolean', value: boolean }
 */

export class ConfError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

const BARE = /[A-Za-z0-9_-]/
const INT = /^[+-]?[0-9]+(_[0-9]+)*$/
const FLOAT =
  /^[+-]?[0-9]+(_[0-9]+)*(\.[0-9]+(_[0-9]+)*)?([eE][+-]?[0-9]+(_[0-9]+)*)?$/

function newTable() {
  return { kind: 'table', map: new Map(), header: false }
}

/** Renders a path of segments, a key or an array index, as text. */
export function renderPath(segments) {
  let out = ''
  let started = false
  for (const segment of segments) {
    if (segment.index !== undefined) {
      out += `[${segment.index}]`
    } else {
      out += started ? `.${segment.key}` : segment.key
      started = true
    }
  }
  return out
}

/** One line of the document, scanned left to right. */
class Line {
  constructor(text, number) {
    this.s = text
    this.n = text.length
    this.i = 0
    this.line = number
  }

  fail(reason) {
    throw new ConfError(this.line, reason)
  }

  /** Skips spaces and tabs. */
  space() {
    while (this.i < this.n && (this.s[this.i] === ' ' || this.s[this.i] === '\t')) this.i++
  }

  /** True at the end of the line, where a comment also ends it. */
  done() {
    return this.i >= this.n || this.s[this.i] === '#' || this.s[this.i] === ';'
  }

  at() {
    return this.i < this.n ? this.s[this.i] : ''
  }

  basicString() {
    this.i++
    let out = ''
    for (;;) {
      if (this.i >= this.n) this.fail('unterminated string')
      const c = this.s[this.i]
      if (c === '"') {
        this.i++
        return out
      }
      if (c === '\\') {
        this.i++
        if (this.i >= this.n) this.fail('unterminated string')
        const e = this.s[this.i]
        if (e === '"') out += '"'
        else if (e === '\\') out += '\\'
        else if (e === 'n') out += '\n'
        else if (e === 't') out += '\t'
        else if (e === 'r') out += '\r'
        else if (e === '0') out += '\0'
        else if (e === 'u') {
          const hex = this.s.slice(this.i + 1, this.i + 5)
          if (!/^[0-9a-fA-F]{4}$/.test(hex)) this.fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(hex, 16))
          this.i += 4
        } else {
          this.fail(`invalid escape \\${e}`)
        }
        this.i++
        continue
      }
      out += c
      this.i++
    }
  }

  literalString() {
    this.i++
    const start = this.i
    while (this.i < this.n && this.s[this.i] !== "'") this.i++
    if (this.i >= this.n) this.fail('unterminated string')
    const out = this.s.slice(start, this.i)
    this.i++
    return out
