  name() {
    const c = this.at()
    if (c === '"') return this.basicString()
    if (c === "'") return this.literalString()
    const start = this.i
    while (this.i < this.n && BARE.test(this.s[this.i])) this.i++
    if (this.i === start) this.fail('expected a name')
    return this.s.slice(start, this.i)
  }

  dottedName() {
    const names = [this.name()]
    for (;;) {
      const save = this.i
      this.space()
      if (this.at() === '.') {
        this.i++
        this.space()
        names.push(this.name())
      } else {
        this.i = save
        return names
      }
    }
  }

  value(path) {
    this.space()
    if (this.done()) this.fail('expected a value')
    const c = this.at()
    if (c === ',' || c === ']' || c === '}') this.fail('expected a value')
    if (c === '"') return { kind: 'string', value: this.basicString() }
    if (c === "'") return { kind: 'string', value: this.literalString() }
    if (c === '[') return this.array(path)
    if (c === '{') return this.inlineTable(path)

    const start = this.i
    while (this.i < this.n) {
      const d = this.s[this.i]
      if (d === ' ' || d === '\t' || d === ',' || d === ']' || d === '}' || d === ';') break
