  }

  array(path) {
    this.i++
    const items = []
    for (;;) {
      this.space()
      if (this.done()) this.fail('unterminated array')
      if (this.at() === ']') {
        this.i++
        break
      }
      items.push(this.value(path.concat([{ index: items.length }])))
      this.space()
      if (this.done()) this.fail('unterminated array')
      const c = this.at()
      if (c === ',') {
        this.i++
        continue
      }
      if (c === ']') {
        this.i++
        break
      }
      this.fail('unterminated array')
    }
    return { kind: 'array', items, aot: false }
  }

  inlineTable(path) {
    this.i++
    const table = newTable()
    this.space()
