      assign(this, table, path, keys, value)
      this.space()
      if (this.done()) this.fail('unterminated inline table')
      const c = this.at()
      if (c === ',') {
        this.i++
        continue
      }
      if (c === '}') {
        this.i++
        break
      }
      this.fail('unterminated inline table')
    }
    return table
  }
}

/** Walks the dots of a name, creating the tables on the way. */
function walk(line, table, path, keys) {
  let cur = table
  for (let j = 0; j < keys.length - 1; j++) {
    const key = keys[j]
    path.push({ key })
    const held = cur.map.get(key)
    if (held === undefined) {
      const made = newTable()
      cur.map.set(key, made)
      cur = made
    } else if (held.kind === 'table') {
      cur = held
    } else if (held.kind === 'array' && held.aot && held.items.length > 0) {
      path.push({ index: held.items.length - 1 })
      cur = held.items[held.items.length - 1]
    } else {
      line.fail(`${renderPath(path)} is not a table`)
    }
  }
  return cur
}

/** Assigns a value at a dotted name inside a table. */
function assign(line, table, basePath, keys, value) {
  const path = basePath.slice()
  const cur = walk(line, table, path, keys)
  const key = keys[keys.length - 1]
  path.push({ key })
  if (cur.map.has(key)) line.fail(`key ${renderPath(path)} is defined twice`)
  cur.map.set(key, value)
}

/** Parses a whole document and answers its root table. */
export function parse(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = newTable()
  let current = root
  let currentPath = []

  for (let n = 0; n < lines.length; n++) {
    const line = new Line(lines[n], n + 1)
    line.space()
    if (line.done()) continue

    if (line.at() === '[') {
      const array = line.s[line.i + 1] === '['
      line.i += array ? 2 : 1
      line.space()
      const keys = line.dottedName()
      line.space()
      if (array) {
        if (line.at() !== ']' || line.s[line.i + 1] !== ']') line.fail('unterminated table header')
        line.i += 2
      } else {
        if (line.at() !== ']') line.fail('unterminated table header')
        line.i += 1
      }
      line.space()
      if (!line.done()) line.fail('trailing text after a table header')

      const path = []
      const parent = walk(line, root, path, keys)
      const key = keys[keys.length - 1]
      path.push({ key })
      const held = parent.map.get(key)
      if (array) {
        let holder = held
        if (holder === undefined) {
          holder = { kind: 'array', items: [], aot: true }
          parent.map.set(key, holder)
        } else if (!(holder.kind === 'array' && holder.aot)) {
          line.fail(`${renderPath(path)} is not an array of tables`)
        }
        const made = newTable()
        made.header = true
        holder.items.push(made)
        path.push({ index: holder.items.length - 1 })
        current = made
        currentPath = path
      } else {
        let table = held
        if (table === undefined) {
          table = newTable()
          parent.map.set(key, table)
        } else if (table.kind !== 'table') {
          line.fail(`${renderPath(path)} is not a table`)
        } else if (table.header) {
          line.fail(`table ${renderPath(path)} is defined twice`)
        }
        table.header = true
        current = table
        currentPath = path
      }
      continue
    }

    const keys = line.dottedName()
    line.space()
    if (line.at() !== '=') line.fail('expected key = value')
    line.i++
    const value = line.value(currentPath.concat(keys.map((key) => ({ key }))))
    line.space()
    if (!line.done()) line.fail('trailing text after a value')
    assign(line, current, currentPath, keys, value)
  }

  return root
}
