        if (depth === 0) return
        continue
      }
      this.advance()
    }
  }

  scanToken() {
    const line = this.line
    const column = this.column
    const c = this.peek()

    if (c === 'r' && this.peek(1) === '"') return this.scanRawString(line, column)
    if (isIdentStart(c)) return this.scanWord(line, column)
    if (isDigit(c)) return this.scanNumber(line, column)
    if (c === '"') return this.scanString(line, column)

    const punct = this.scanPunct(line, column)
    if (punct) return punct

    this.advance()
    this.fail(line, column, `unexpected character ${c}`)
  }

  scanWord(line, column) {
    const start = this.i
    while (isIdentPart(this.peek())) this.advance()
    const text = this.textFrom(start)
    return { line, column, kind: KEYWORDS.has(text) ? 'keyword' : 'ident', body: text }
  }

  /**
   * Reads a run of digits in which a `_` is only allowed between two digits.
   * Returns whether the run held at least one digit.
   */
  readDigitRun(accepts) {
    if (!this.peek() || !accepts(this.peek())) return false
    this.advance()
    for (;;) {
      const c = this.peek()
      if (c !== undefined && accepts(c)) {
        this.advance()
        continue
      }
      const next = this.peek(1)
      if (c === '_' && next !== undefined && accepts(next)) {
        this.advance()
        this.advance()
        continue
      }
      return true
    }
  }

  scanNumber(line, column) {
    const start = this.i
    const badNumber = () => {
      while (isIdentPart(this.peek())) this.advance()
      this.fail(line, column, `invalid number ${this.textFrom(start)}`)
    }

    if (this.peek() === '0' && 'xXbBoO'.includes(this.peek(1) ?? '')) {
      const marker = this.peek(1).toLowerCase()
      const accepts = marker === 'x' ? isHex : marker === 'b' ? isBin : isOctal
      this.advance()
      this.advance()
      if (!this.readDigitRun(accepts)) badNumber()
    } else {
      this.readDigitRun(isDigit)
      if (this.peek() === '.' && isDigit(this.peek(1) ?? '')) {
        this.advance()
        this.readDigitRun(isDigit)
      }
      const marker = this.peek()
      if (marker === 'e' || marker === 'E') {
        const signed = this.peek(1) === '+' || this.peek(1) === '-'
        const digit = this.peek(signed ? 2 : 1)
        if (digit !== undefined && isDigit(digit)) {
          this.advance()
          if (signed) this.advance()
          this.readDigitRun(isDigit)
        }
      }
    }

    if (isIdentPart(this.peek())) badNumber()
    return { line, column, kind: 'number', body: this.textFrom(start) }
  }

  scanString(line, column) {
    this.advance() // the opening quote
    let value = ''
    for (;;) {
      if (this.done) this.fail(line, column, 'unterminated string')
      const c = this.peek()
      if (c === '\n') this.fail(this.line, this.column, 'newline in string')
      if (c === '"') {
        this.advance()
        return { line, column, kind: 'string', body: value }
      }
      if (c === '\\') {
        value += this.scanEscape(line, column)
        continue
      }
      value += this.advance()
    }
  }

  /** Reads one escape sequence and returns the text it stands for. */
  scanEscape(stringLine, stringColumn) {
    const line = this.line
    const column = this.column
    this.advance() // the backslash
    if (this.done) this.fail(stringLine, stringColumn, 'unterminated string')
    const c = this.peek()
    const bad = () => this.fail(line, column, `invalid escape \\${c}`)
    const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }

    if (Object.hasOwn(simple, c) && c !== undefined) {
      this.advance()
      return simple[c]
    }
    if (c === 'x') {
      const first = this.peek(1)
      const second = this.peek(2)
      if (first === undefined || second === undefined || !isHex(first) || !isHex(second)) bad()
      this.advance()
      this.advance()
      this.advance()
      return String.fromCodePoint(parseInt(first + second, 16))
    }
    if (c === 'u') {
      if (this.peek(1) !== '{') bad()
      let offset = 2
      let digits = ''
      while (this.peek(offset) !== undefined && isHex(this.peek(offset))) {
        digits += this.peek(offset)
        offset += 1
      }
      if (digits === '' || this.peek(offset) !== '}') bad()
      const code = parseInt(digits, 16)
      if (code > 0x10ffff) bad()
      for (let step = 0; step <= offset; step += 1) this.advance()
      return String.fromCodePoint(code)
    }
    bad()
  }

  scanRawString(line, column) {
    this.advance() // the `r`
    this.advance() // the opening quote
    let value = ''
    for (;;) {
      if (this.done) this.fail(line, column, 'unterminated string')
      const c = this.advance()
      if (c === '"') return { line, column, kind: 'rawstring', body: value }
      value += c
    }
  }

  scanPunct(line, column) {
    const two = (this.peek() ?? '') + (this.peek(1) ?? '')
    const doubles = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
    const singles = '+-*/%=<>!(){}[],;.'
    if (doubles.includes(two)) {
      this.advance()
      this.advance()
      return { line, column, kind: 'punct', body: two }
    }
    const c = this.peek()
    if (c !== undefined && singles.includes(c)) {
      this.advance()
      return { line, column, kind: 'punct', body: c }
    }
    return null
  }
}

export function scan(source) {
  return new Scanner(source).scan()
}

export const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']
"}

