{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { readFileSync } from 'node:fs'
import { scan, ScanError, KINDS } from './scanner.js'

function die(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function renderTokens(tokens) {
  return tokens
    .map((token) => {
      const body =
        token.kind === 'string' || token.kind === 'rawstring'
          ? JSON.stringify(token.body)
          : token.body
      return `${token.line}:${token.column} ${token.kind} ${body}\n`
    })
    .join('')
}

function renderStats(tokens) {
  const lines = KINDS.map(
    (kind) => `${kind} ${tokens.filter((token) => token.kind === kind).length}\n`,
  )
  lines.push(`total ${tokens.length}\n`)
  return lines.join('')
}

function main(argv) {
  const mode = argv[0]
  if (argv.length !== 1 || (mode !== 'tokens' && mode !== 'stats')) {
    die('usage: cli.js tokens|stats')
  }

  let tokens
  try {
    tokens = scan(readStdin())
  } catch (error) {
    if (error instanceof ScanError) die(error.message)
    throw error
  }

  process.stdout.write(mode === 'tokens' ? renderTokens(tokens) : renderStats(tokens))
}

main(process.argv.slice(2))
"}

