const NAME = /^[A-Za-z0-9_.-]+$/
const COST = /^[0-9]+$/

/** Splits the input text into the lines a directive may sit on. */
export function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function checkName(name, lineNo) {
  if (!NAME.test(name)) throw fail(`line ${lineNo}: invalid task name ${name}`)
}

/**
 * Reads the build graph. Returns a map from name to `{ name, cost, deps }`,
 * where `deps` is the set of names the task depends on.
 */
export function parseGraph(text) {
  const tasks = new Map()
  const edges = []
  const used = []

  const lines = splitLines(text)
  for (let i = 0; i < lines.length; i += 1) {
    const lineNo = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const words = line.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) throw fail(`line ${lineNo}: expected task <name> <cost>`)
      const [, name, cost] = words
      checkName(name, lineNo)
      if (!COST.test(cost)) throw fail(`line ${lineNo}: cost must be a non-negative integer`)
      if (tasks.has(name)) throw fail(`line ${lineNo}: task ${name} is declared twice`)
      tasks.set(name, { name, cost: Number(cost), deps: new Set() })
    } else if (directive === 'dep') {
      if (words.length < 3) throw fail(`line ${lineNo}: expected dep <name> <dependency>...`)
      for (let w = 1; w < words.length; w += 1) checkName(words[w], lineNo)
      const name = words[1]
      used.push(name)
      for (let w = 2; w < words.length; w += 1) {
        used.push(words[w])
        edges.push([name, words[w]])
      }
    } else {
      throw fail(`line ${lineNo}: unknown directive ${directive}`)
    }
  }

  for (const name of used) {
    if (!tasks.has(name)) throw fail(`unknown task ${name}`)
  }
  for (const [from, to] of edges) tasks.get(from).deps.add(to)

  return tasks
}

/** The task names in ascending order. */
export function sortedNames(tasks) {
  return [...tasks.keys()].sort()
}
