import { depsOf, priorities } from './graph.js'

/**
 * Simulates the graph on `workers` workers. Returns the run of each worker in
 * index order and the makespan.
 */
export function pack(tasks, workers) {
  const names = sortedNames(tasks)
  const priority = priorities(tasks)
  const deps = new Map(names.map((n) => [n, depsOf(tasks, n)]))
  const freeAt = new Array(workers).fill(0)
  const runs = Array.from({ length: workers }, () => [])
  const finished = new Map()
  const started = new Set()
  let now = 0
  let makespan = 0

  while (started.size < names.length) {
    let progressed = true
    while (progressed) {
      progressed = false
      let worker = -1
      for (let i = 0; i < workers; i += 1) {
        if (freeAt[i] <= now) {
          worker = i
          break
        }
      }
      if (worker === -1) break

      let best = null
      for (const name of names) {
        if (started.has(name)) continue
        let ready = true
        for (const dep of deps.get(name)) {
          const end = finished.get(dep)
          if (end === undefined || end > now) {
            ready = false
            break
          }
        }
        if (!ready) continue
        if (best === null || priority.get(name) > priority.get(best)) best = name
      }
      if (best === null) break

      const finish = now + tasks.get(best).cost
      started.add(best)
      finished.set(best, finish)
      freeAt[worker] = finish
      runs[worker].push({ name: best, start: now, finish })
      if (finish > makespan) makespan = finish
      progressed = true
    }

    if (started.size === names.length) break

    let next = null
    for (let i = 0; i < workers; i += 1) {
      if (freeAt[i] > now && (next === null || freeAt[i] < next)) next = freeAt[i]
    }
    if (next === null) break
    now = next
  }

  return { runs, makespan }
}
