{"file_path":"src/sheet.js","content":"/** Reading a sheet: one cell per line, `<address><spaces><content>`. */

import { parseAddress } from './address.js'
import { parseFormula, hasMisplacedRange } from './formula.js'

/**
 * Returns { cells } where cells maps an address to
 * { content, formula } (formula is null for a literal or a bad formula),
 * or { error } with the message of the first failure.
 */
export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i].replace(/^[ \t]+/, '')
    if (line === '' || line.startsWith('#')) continue

    let end = 0
    while (end < line.length && line[end] !== ' ' && line[end] !== '\t') end++
    const addressText = line.slice(0, end)
    let rest = line.slice(end)
    const skip = /^[ \t]+/.exec(rest)
    if (skip) rest = rest.slice(skip[0].length)

    const parsed = parseAddress(addressText)
    if (!parsed) {
      return { error: `line ${lineNo}: invalid cell address ${addressText}` }
    }
    if (cells.has(parsed.addr)) {
      return { error: `line ${lineNo}: cell ${parsed.addr} is declared twice` }
    }

    const cell = { content: rest, formula: null, bad: false }
    if (rest.startsWith('=')) {
      const ast = parseFormula(rest.slice(1))
      if (ast === null) {
        cell.bad = true
      } else {
        cell.formula = ast
        cell.misplacedRange = hasMisplacedRange(ast)
      }
    }
    cells.set(parsed.addr, cell)
  }
  return { cells }
}
"}

{"file_path":"src/formula.js","content":"/** The formula grammar: tokens and a recursive descent parser. */

const COMPARISONS = ['=', '<>', '<=', '>=', '<', '>']

/** Splits a formula body into tokens, or returns null when a character is bad. */
export function tokenize(src) {
  const tokens = []
  let i = 0
  while (i < src.length) {
    const ch = src[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }
    if (ch >= '0' && ch <= '9') {
      const m = /^[0-9]+(\.[0-9]+)?/.exec(src.slice(i))
      const raw = m[0]
      i += raw.length
      if (src[i] === '.') return null
      tokens.push({ type: 'num', value: Number(raw) })
      continue
    }
    if (/[A-Za-z]/.test(ch)) {
      const m = /^[A-Za-z][A-Za-z0-9]*/.exec(src.slice(i))
      i += m[0].length
      tokens.push({ type: 'word', value: m[0].toUpperCase() })
      continue
    }
    if (ch === '(' || ch === ')' || ch === ',' || ch === ':') {
      tokens.push({ type: ch })
      i++
      continue
    }
    const two = src.slice(i, i + 2)
    if (two === '<>' || two === '<=' || two === '>=') {
      tokens.push({ type: 'op', value: two })
      i += 2
      continue
    }
    if ('^*/+-=<>'.includes(ch)) {
      tokens.push({ type: 'op', value: ch })
      i++
      continue
    }
    return null
  }
  return tokens
}

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.i = 0
  }

  peek() {
    return this.tokens[this.i]
  }

  at(type, value) {
    const t = this.peek()
    if (!t || t.type !== type) return false
    return value === undefined || t.value === value
  }

  next() {
    return this.tokens[this.i++]
  }

  parseExpression() {
    return this.parseComparison()
  }

  parseComparison() {
    let left = this.parseAdditive()
    if (!left) return null
    while (this.peek() && this.peek().type === 'op' && COMPARISONS.includes(this.peek().value)) {
      const op = this.next().value
      const right = this.parseAdditive()
      if (!right) return null
      left = { type: 'bin', op, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    if (!left) return null
    while (this.peek() && this.peek().type === 'op' && (this.peek().value === '+' || this.peek().value === '-')) {
      const op = this.next().value
      const right = this.parseMultiplicative()
      if (!right) return null
      left = { type: 'bin', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    if (!left) return null
    while (this.peek() && this.peek().type === 'op' && (this.peek().value === '*' || this.peek().value === '/')) {
      const op = this.next().value
      const right = this.parsePower()
      if (!right) return null
      left = { type: 'bin', op, left, right }
    }
    return left
  }

  parsePower() {
    const left = this.parseUnary()
    if (!left) return null
    if (this.at('op', '^')) {
      this.next()
      const right = this.parsePower()
      if (!right) return null
      return { type: 'bin', op: '^', left, right }
    }
    return left
  }

  parseUnary() {
    if (this.at('op', '-') || this.at('op', '+')) {
      const op = this.next().value
      const operand = this.parseUnary()
      if (!operand) return null
      return { type: 'unary', op, operand }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const t = this.peek()
    if (!t) return null
    if (t.type === 'num') {
      this.next()
      return { type: 'num', value: t.value }
    }
    if (t.type === '(') {
      this.next()
      const inner = this.parseExpression()
      if (!inner) return null
      if (!this.at(')')) return null
      this.next()
      return inner
    }
    if (t.type === 'word') {
      this.next()
      if (this.at('(')) {
        this.next()
        const args = []
        if (!this.at(')')) {
          for (;;) {
            const arg = this.parseExpression()
            if (!arg) return null
            args.push(arg)
            if (this.at(',')) {
              this.next()
              continue
            }
            break
          }
        }
        if (!this.at(')')) return null
        this.next()
        return { type: 'call', name: t.value, args }
      }
      if (this.at(':')) {
        this.next()
        if (!this.at('word')) return null
        const end = this.next().value
        return { type: 'range', from: t.value, to: end }
      }
      if (t.value === 'TRUE') return { type: 'bool', value: true }
      if (t.value === 'FALSE') return { type: 'bool', value: false }
      return { type: 'ref', name: t.value }
    }
    return null
  }
}

/** Parses a formula body into an AST, or null when the grammar rejects it. */
export function parseFormula(body) {
  const tokens = tokenize(body)
  if (tokens === null) return null
  const parser = new Parser(tokens)
  const ast = parser.parseExpression()
  if (!ast || parser.i !== tokens.length) return null
  return ast
}

/** True when a range sits anywhere but directly as a function argument. */
export function hasMisplacedRange(node, allowed = false) {
  switch (node.type) {
    case 'range':
      return !allowed
    case 'bin':
      return hasMisplacedRange(node.left) || hasMisplacedRange(node.right)
    case 'unary':
      return hasMisplacedRange(node.operand)
    case 'call':
      return node.args.some((a) => hasMisplacedRange(a, true))
    default:
      return false
  }
}
"}

