{"file_path":"src/eval.js","content":"/** Evaluating cells and formulas, and listing the cells they name. */

import { parseAddress, expandRange, compareAddresses } from './address.js'
import {
  num,
  bool,
  err,
  range,
  isError,
  literalValue,
  toNumber,
  finite,
  ERR,
  REF,
  NAME,
  CYCLE,
  VALUE,
  DIV0,
} from './value.js'

const VARIADIC = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'])
const FUNCTIONS = new Set([...VARIADIC, 'ABS', 'IF'])

function kindRank(v) {
  if (v.kind === 'num') return 0
  if (v.kind === 'text') return 1
  return 2
}

function compareText(a, b) {
  const x = [...a]
  const y = [...b]
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const ca = x[i].codePointAt(0)
    const cb = y[i].codePointAt(0)
    if (ca !== cb) return ca < cb ? -1 : 1
  }
  return x.length === y.length ? 0 : x.length < y.length ? -1 : 1
}

function orderOf(a, b) {
  const ra = kindRank(a)
  const rb = kindRank(b)
  if (ra !== rb) return ra < rb ? -1 : 1
  if (ra === 0) return a.n === b.n ? 0 : a.n < b.n ? -1 : 1
  if (ra === 1) return compareText(a.s, b.s)
  const x = a.b ? 1 : 0
  const y = b.b ? 1 : 0
  return x === y ? 0 : x < y ? -1 : 1
}

function applyComparison(op, cmp) {
  switch (op) {
    case '=':
      return cmp === 0
    case '<>':
      return cmp !== 0
    case '<':
      return cmp < 0
    case '<=':
      return cmp <= 0
    case '>':
      return cmp > 0
    default:
      return cmp >= 0
  }
}

export class Engine {
  constructor(cells) {
    this.cells = cells
    this.cache = new Map()
    this.stack = new Set()
  }

  valueOf(addr) {
    if (this.stack.has(addr)) return CYCLE
    if (this.cache.has(addr)) return this.cache.get(addr)
    this.stack.add(addr)
    let result
    const cell = this.cells.get(addr)
    if (cell === undefined) {
      result = num(0)
    } else if (cell.bad) {
      result = ERR
    } else if (cell.formula) {
      result = cell.misplacedRange ? ERR : this.evalNode(cell.formula)
    } else {
      result = literalValue(cell.content)
    }
    if (result.kind === 'range') result = ERR
    this.stack.delete(addr)
    this.cache.set(addr, result)
    return result
  }

  depsOf(addr) {
    const cell = this.cells.get(addr)
    const found = new Set()
    if (cell && cell.formula) collectDeps(cell.formula, found)
    return [...found].sort(compareAddresses)
  }

  evalNode(node) {
    switch (node.type) {
      case 'num':
        return num(node.value)
      case 'bool':
        return bool(node.value)
      case 'ref': {
        const parsed = parseAddress(node.name)
        if (!parsed) return REF
        return this.valueOf(parsed.addr)
      }
      case 'range': {
        const a = parseAddress(node.from)
        const b = parseAddress(node.to)
        if (!a || !b) return REF
        return range(expandRange(a, b).map((cell) => this.valueOf(cell)))
      }
      case 'unary': {
        const v = this.evalNode(node.operand)
        const n = toNumber(v)
        if (isError(n)) return n
        return node.op === '-' ? finite(-n.n) : finite(n.n)
      }
      case 'bin':
        return this.evalBinary(node)
      case 'call':
        return this.evalCall(node)
      default:
        return ERR
    }
  }

  evalBinary(node) {
    const left = this.evalNode(node.left)
    if (isError(left)) return left
    const right = this.evalNode(node.right)
    if (isError(right)) return right

    if (['=', '<>', '<', '<=', '>', '>='].includes(node.op)) {
      if (left.kind === 'range' || right.kind === 'range') return ERR
      return bool(applyComparison(node.op, orderOf(left, right)))
    }

    const a = toNumber(left)
    if (isError(a)) return a
    const b = toNumber(right)
    if (isError(b)) return b

    switch (node.op) {
      case '+':
        return finite(a.n + b.n)
      case '-':
        return finite(a.n - b.n)
      case '*':
        return finite(a.n * b.n)
      case '/':
        if (b.n === 0) return DIV0
        return finite(a.n / b.n)
      case '^':
        return finite(a.n ** b.n)
      default:
        return ERR
    }
  }

  evalCall(node) {
    const name = node.name
    if (!FUNCTIONS.has(name)) return NAME
    const arity = node.args.length
    if (VARIADIC.has(name) ? arity < 1 : name === 'IF' ? arity !== 3 : arity !== 1) {
      return ERR
    }

    if (name === 'IF') return this.evalIf(node.args)

    const values = []
    for (const arg of node.args) {
      const v = this.evalNode(arg)
      if (v.kind === 'range') {
        for (const item of v.cells) {
          if (isError(item)) return item
          values.push(item)
        }
      } else {
        if (isError(v)) return v
        values.push(v)
      }
    }

    if (name === 'COUNT') {
      return num(values.filter((v) => v.kind === 'num').length)
    }
    if (values.length === 0) return ERR

    const numbers = []
    for (const v of values) {
      const n = toNumber(v)
      if (isError(n)) return n
      numbers.push(n.n)
    }

    switch (name) {
      case 'SUM':
        return finite(numbers.reduce((s, x) => s + x, 0))
      case 'MIN':
        return finite(Math.min(...numbers))
      case 'MAX':
        return finite(Math.max(...numbers))
      case 'AVG':
        return finite(numbers.reduce((s, x) => s + x, 0) / numbers.length)
      default: {
        if (numbers.length !== 1) return ERR
        return finite(Math.abs(numbers[0]))
      }
    }
  }

  evalIf(args) {
    let cond = this.evalNode(args[0])
    if (cond.kind === 'range') {
      for (const item of cond.cells) if (isError(item)) return item
      if (cond.cells.length !== 1) return ERR
      cond = cond.cells[0]
    }
    if (isError(cond)) return cond
    const n = toNumber(cond)
    if (isError(n)) return n
    const branch = n.n !== 0 ? args[1] : args[2]
    const value = this.evalNode(branch)
    return value.kind === 'range' ? ERR : value
  }
}

function collectDeps(node, found) {
  switch (node.type) {
    case 'ref': {
      const parsed = parseAddress(node.name)
      if (parsed) found.add(parsed.addr)
      return
    }
    case 'range': {
      const a = parseAddress(node.from)
      const b = parseAddress(node.to)
      if (a && b) for (const cell of expandRange(a, b)) found.add(cell)
      return
    }
    case 'bin':
      collectDeps(node.left, found)
      collectDeps(node.right, found)
      return
    case 'unary':
      collectDeps(node.operand, found)
      return
    case 'call':
      for (const arg of node.args) collectDeps(arg, found)
      return
    default:
  }
}
"}

