 * The two ways out: canonical JSON, and one line per node for `keys`.
 */

import { typeName, childPath, indexPath } from './nodes.js'

/** Ascending order by code point, which surrogate pairs would otherwise break. */
function byCodePoint(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  for (let i = 0; i < x.length && i < y.length; i += 1) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d !== 0) return d
  }
  return x.length - y.length
}

function sortedKeys(node) {
  return Array.from(node.map.keys()).sort(byCodePoint)
}

function number(v) {
  return Number.isFinite(v) ? String(v) : 'null'
}

function render(node, indent) {
  const pad = '  '.repeat(indent)
  const inner = '  '.repeat(indent + 1)
  if (node.kind === 'table') {
    const keys = sortedKeys(node)
    if (keys.length === 0) return '{}'
    const parts = keys.map((k) => `${inner}${JSON.stringify(k)}: ${render(node.map.get(k), indent + 1)}`)
    return `{\n${parts.join(',\n')}\n${pad}}`
  }
