const isHex = (c) => c !== null && /^[0-9a-fA-F]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== null && c >= '0' && c <= '7'
const isAlpha = (c) => c !== null && /^[A-Za-z_]$/.test(c)
const isWord = (c) => c !== null && /^[0-9A-Za-z_]$/.test(c)

class Scanner {
  constructor(source) {
    // Positions count code points, so the input is walked code point by code
    // point rather than by UTF-16 unit.
    this.chars = Array.from(source)
    this.pos = 0
    this.line = 1
    this.column = 1
  }

  peek(offset = 0) {
    const index = this.pos + offset
    return index < this.chars.length ? this.chars[index] : null
  }

  atEnd() {
    return this.pos >= this.chars.length
  }

  take() {
    const ch = this.chars[this.pos]
    this.pos += 1
    if (ch === '\n') {
      this.line += 1
      this.column = 1
    } else if (ch === '\t') {
      this.column = Math.floor((this.column - 1) / 4) * 4 + 5
    } else {
      this.column += 1
    }
    return ch
  }

  /** Eats the trailing run of word characters that spoiled a number. */
  takeWordRun() {
    let text = ''
    while (isWord(this.peek())) text += this.take()
    return text
  }

  scan() {
    const tokens = []
    for (;;) {
      this.skipTrivia()
      if (this.atEnd()) return tokens
      tokens.push(this.readToken())
    }
  }

  skipTrivia() {
    for (;;) {
      const ch = this.peek()
      if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') {
        this.take()
      } else if (ch === '/' && this.peek(1) === '/') {
        while (!this.atEnd() && this.peek() !== '\n') this.take()
      } else if (ch === '/' && this.peek(1) === '*') {
        this.skipBlockComment()
      } else {
        return
      }
    }
  }

  skipBlockComment() {
    const line = this.line
    const column = this.column
    this.take()
    this.take()
    let depth = 1
    while (depth > 0) {
      if (this.atEnd()) throw new ScanError(line, column, 'unterminated block comment')
      if (this.peek() === '/' && this.peek(1) === '*') {
        this.take()
        this.take()
        depth += 1
      } else if (this.peek() === '*' && this.peek(1) === '/') {
        this.take()
        this.take()
        depth -= 1
      } else {
        this.take()
      }
    }
  }

  readToken() {
    const ch = this.peek()
    if (ch === 'r' && this.peek(1) === '"') return this.readRawString()
    if (isAlpha(ch)) return this.readWord()
    if (isDec(ch)) return this.readNumber()
    if (ch === '"') return this.readString()
    return this.readPunct()
  }

  readWord() {
    const line = this.line
    const column = this.column
    let text = ''
    while (isWord(this.peek())) text += this.take()
    return { kind: KEYWORDS.has(text) ? 'keyword' : 'ident', line, column, body: text }
  }

  /**
   * Reads a run of digits of one class, letting `_` sit between two digits of
   * that same run and nowhere else. Answers how many digits it read.
   */
  readDigits(isDigit, sink) {
    let count = 0
    for (;;) {
      const ch = this.peek()
      if (isDigit(ch)) {
        sink.text += this.take()
        count += 1
      } else if (ch === '_' && count > 0 && isDigit(this.peek(1))) {
        sink.text += this.take()
      } else {
        return count
      }
    }
  }

  readNumber() {
    const line = this.line
    const column = this.column
    const sink = { text: '' }

    const prefix = this.peek() === '0' ? this.peek(1) : null
    let isDigit = null
    if (prefix === 'x' || prefix === 'X') isDigit = isHex
    else if (prefix === 'b' || prefix === 'B') isDigit = isBin
    else if (prefix === 'o' || prefix === 'O') isDigit = isOct

    if (isDigit !== null) {
      sink.text += this.take()
      sink.text += this.take()
      if (this.readDigits(isDigit, sink) === 0) {
        sink.text += this.takeWordRun()
        throw new ScanError(line, column, `invalid number ${sink.text}`)
      }
    } else {
      this.readDigits(isDec, sink)
      // A `.` only continues the number when a digit follows it.
      if (this.peek() === '.' && isDec(this.peek(1))) {
        sink.text += this.take()
