      const here = childPath(pathOf(node), part)
      let next = node.map.get(part)
      if (next === undefined) {
        next = newTable(false)
        setPath(next, here)
        node.map.set(part, next)
      }
      if (next.kind === 'arraytable') {
        const last = next.items[next.items.length - 1]
        if (last === undefined) throw new ConfError(line, `${here} is not a table`)
        next = last
      } else if (next.kind !== 'table') {
        throw new ConfError(line, `${here} is not a table`)
      }
      node = next
    }
    return node
  }

  /** The path a name will hold, worked out without changing the tree. */
  const preview = (table, parts) => {
    let node = table
    let path = pathOf(table)
    for (let k = 0; k < parts.length; k += 1) {
      path = childPath(path, parts[k])
      if (k === parts.length - 1) break
      const next = node && node.kind === 'table' ? node.map.get(parts[k]) : undefined
      if (next && next.kind === 'arraytable') {
        path = indexPath(path, Math.max(next.items.length - 1, 0))
        node = next.items[next.items.length - 1]
      } else {
        node = next && next.kind === 'table' ? next : null
      }
    }
    return path
  }

  const assign = (table, parts, value, line) => {
    const holder = walk(table, parts.slice(0, -1), line)
    const key = parts[parts.length - 1]
    const path = childPath(pathOf(holder), key)
    if (holder.map.has(key)) throw new ConfError(line, `key ${path} is defined twice`)
    holder.map.set(key, value)
    setPath(value, path)
  }

  const ctx = { assign, preview, setPath, prefix: '' }
  let current = root

  const lines = splitLines(text)
  for (let n = 0; n < lines.length; n += 1) {
    const line = n + 1
    const reader = new LineReader(lines[n], line)
    reader.skipSpace()
    if (reader.atEnd()) continue

    if (reader.peek() === '[') {
      reader.i += 1
      const isArray = reader.peek() === '['
      if (isArray) reader.i += 1
      reader.skipSpace()
      const parts = reader.dottedName()
      reader.skipSpace()
