      const key = parts[parts.length - 1]
      const path = childPath(pathOf(holder), key)
      const held = holder.map.get(key)
      if (isArray) {
        let target = held
        if (target === undefined) {
          target = newArrayTable()
          setPath(target, path)
          holder.map.set(key, target)
        } else if (target.kind !== 'arraytable') {
          throw new ConfError(line, `${path} is not an array of tables`)
        }
        const fresh = newTable(true)
        setPath(fresh, indexPath(path, target.items.length))
        target.items.push(fresh)
        current = fresh
      } else if (held === undefined) {
        const fresh = newTable(true)
        setPath(fresh, path)
        holder.map.set(key, fresh)
        current = fresh
      } else if (held.kind !== 'table') {
        throw new ConfError(line, `${path} is not a table`)
      } else if (held.explicit) {
        throw new ConfError(line, `table ${path} is defined twice`)
      } else {
        held.explicit = true
        current = held
      }
      continue
    }

    const parts = reader.dottedName()
    reader.skipSpace()
    if (reader.peek() !== '=') reader.fail('expected key = value')
    reader.i += 1
    const value = reader.value({ ...ctx, prefix: preview(current, parts) })
    reader.skipSpace()
    if (!reader.atEnd()) reader.fail('trailing text after a value')
    assign(current, parts, value, line)
  }

  return root
}
