/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

import { readFileSync } from 'node:fs'
import { parse } from './parse.js'
import { toJson, toKeys } from './output.js'
import { ConfError } from './errors.js'

function die(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

const argv = process.argv.slice(2)
if (argv.length !== 1 || (argv[0] !== 'json' && argv[0] !== 'keys')) {
  die('usage: cli.js json|keys')
}

let input = ''
try {
  input = readFileSync(0, 'utf8')
} catch {
  input = ''
}

let out
try {
  const root = parse(input)
  out = argv[0] === 'json' ? toJson(root) : toKeys(root)
} catch (err) {
  if (err instanceof ConfError) die(err.message)
  throw err
}

process.stdout.write(out)
"}

