{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { readFileSync } from 'node:fs'
import { parse, ParseError } from './parse.js'
import { count } from './count.js'
import { render } from './render.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exitCode = 2
}

function main() {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || (argv[0] !== 'rounds' && argv[0] !== 'tally')) {
    fail('usage: cli.js rounds|tally')
    return
  }
  const mode = argv[0]

  let input = ''
  try {
    input = readFileSync(0, 'utf8')
  } catch {
    input = ''
  }

  let election
  try {
    election = parse(input)
  } catch (err) {
    if (err instanceof ParseError) {
      fail(err.message)
      return
    }
    throw err
  }

  const result = count(election)
  process.stdout.write(render(mode, result))
}

main()
"}

