{"file_path":"src/parse.js","content":"/** Parsing of the election input into candidates and weighted ballots. */

export class ParseError extends Error {}

const NAME = /^[A-Za-z0-9_-]+$/
const COUNT = /^[1-9][0-9]*$/

function lineError(lineNumber, message) {
  return new ParseError(`line ${lineNumber}: ${message}`)
}

export function parse(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let candidates = null
  const declared = new Set()
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const tokens = line.split(/\s+/)
    const word = tokens[0]

    if (word === 'candidates') {
      if (candidates !== null) {
        throw lineError(lineNumber, 'candidates must be declared once, before any ballot')
      }
      if (tokens.length < 2) {
        throw lineError(lineNumber, 'expected candidates <name>...')
      }
      const names = []
      for (let j = 1; j < tokens.length; j++) {
        const name = tokens[j]
        if (!NAME.test(name)) {
          throw lineError(lineNumber, `invalid candidate name ${name}`)
        }
        if (declared.has(name)) {
          throw lineError(lineNumber, `candidate ${name} is declared twice`)
        }
        declared.add(name)
        names.push(name)
      }
      candidates = names
    } else if (word === 'ballot') {
      if (candidates === null) {
        throw lineError(lineNumber, 'candidates must be declared once, before any ballot')
      }
      if (tokens.length < 3) {
        throw lineError(lineNumber, 'expected ballot <count> <candidate>...')
      }
      if (!COUNT.test(tokens[1])) {
        throw lineError(lineNumber, 'count must be a positive integer')
      }
      const weight = Number(tokens[1])
      const prefs = []
      const seen = new Set()
      for (let j = 2; j < tokens.length; j++) {
        const name = tokens[j]
        if (!declared.has(name)) {
          throw lineError(lineNumber, `unknown candidate ${name}`)
        }
        if (seen.has(name)) {
          throw lineError(lineNumber, `candidate ${name} is repeated`)
        }
        seen.add(name)
        prefs.push(name)
      }
      ballots.push({ weight, prefs })
    } else {
      throw lineError(lineNumber, `unknown directive ${word}`)
    }
  }

  if (candidates === null) {
    throw new ParseError('no candidates')
  }

  return { candidates, ballots }
}
"}

{"file_path":"src/count.js","content":"/** The instant-runoff count itself. */

function byCodePoint(a, b) {
  if (a < b) return -1
  if (a > b) return 1
  return 0
}

/** Pick the candidate to eliminate among those tied for fewest votes. */
function pickEliminated(tiedInput, history) {
  let tied = tiedInput.slice()
  for (let r = 0; r < history.length && tied.length > 1; r++) {
    const votes = history[r]
    let least = Infinity
    for (const name of tied) {
      const v = votes.get(name) ?? 0
      if (v < least) least = v
    }
    tied = tied.filter((name) => (votes.get(name) ?? 0) === least)
  }
  if (tied.length === 1) return tied[0]
  return tied.sort(byCodePoint)[tied.length - 1]
}

export function count({ candidates, ballots }) {
  const total = ballots.reduce((sum, b) => sum + b.weight, 0)
  const continuing = new Set(candidates)
  const rounds = []
  const history = []
  let winner = null

  for (;;) {
    const votes = new Map()
    for (const name of candidates) {
      if (continuing.has(name)) votes.set(name, 0)
    }
    let active = 0
    for (const ballot of ballots) {
      for (const name of ballot.prefs) {
        if (continuing.has(name)) {
          votes.set(name, votes.get(name) + ballot.weight)
          active += ballot.weight
          break
        }
      }
    }

    const round = {
      votes,
      exhausted: total - active,
      standing: Array.from(continuing),
      eliminated: null,
    }
    rounds.push(round)
    history.push(votes)

    if (active === 0) break

    let majority = null
    for (const [name, v] of votes) {
      if (v * 2 > active) {
        majority = name
        break
      }
    }
    if (majority !== null) {
      winner = majority
      break
    }

    let least = Infinity
    for (const v of votes.values()) if (v < least) least = v
    const tied = []
    for (const [name, v] of votes) if (v === least) tied.push(name)

    const out = tied.length === 1 ? tied[0] : pickEliminated(tied, history)
    round.eliminated = out
    continuing.delete(out)
  }

  return { rounds, winner }
}
"}

{"file_path":"src/render.js","content":"/** Formatting of the count for both output modes. */

export function render(mode, { rounds, winner }) {
  const parts = []
  if (mode === 'rounds') {
    for (let i = 0; i < rounds.length; i++) {
      const round = rounds[i]
      const names = round.standing.slice().sort((a, b) => {
        const va = round.votes.get(a)
        const vb = round.votes.get(b)
        if (va !== vb) return vb - va
        return a < b ? -1 : a > b ? 1 : 0
      })
      const cells = names.map((name) => `${name}=${round.votes.get(name)}`)
      cells.push(`exhausted=${round.exhausted}`)
      parts.push(`round ${i + 1}: ${cells.join(' ')}\n`)
      if (round.eliminated !== null) parts.push(`eliminated ${round.eliminated}\n`)
    }
  } else {
    parts.push(`rounds ${rounds.length}\n`)
  }
  parts.push(winner === null ? 'no winner\n' : `winner ${winner}\n`)
  return parts.join('')
}
"}

