{"file_path":"src/scanner.js","content":"/**
 * Scanner for tokenizing source code.
 * Handles positions, comments, strings, numbers, and punctuation.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null']);

const PUNCT_2CHAR = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>']);

const PUNCT_1CHAR = new Set([
  '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.'
]);

export class Scanner {
  constructor(input) {
    this.input = input;
    this.pos = 0;
    this.line = 1;
    this.column = 1;
    this.tokens = [];
    this.errors = [];
  }

  currentChar() {
    return this.pos < this.input.length ? this.input[this.pos] : null;
  }

  peekChar(offset = 1) {
    const p = this.pos + offset;
    return p < this.input.length ? this.input[p] : null;
  }

  advance() {
    if (this.pos >= this.input.length) return null;
    const ch = this.input[this.pos];
    this.pos++;

    if (ch === '\n') {
      this.line++;
      this.column = 1;
    } else if (ch === '\t') {
      // Tab moves column to next multiple of 4 plus 1
      this.column = Math.floor((this.column - 1 + 4) / 4) * 4 + 1;
    } else {
      this.column++;
    }

    return ch;
  }

  skipWhitespace() {
    while (this.currentChar() && /[ \t\r\n]/.test(this.currentChar())) {
      this.advance();
    }
  }

  skipLineComment() {
    // We're at //, skip to end of line
    this.advance(); // skip first /
    this.advance(); // skip second /
    while (this.currentChar() && this.currentChar() !== '\n') {
      this.advance();
    }
  }

  skipBlockComment() {
    const startLine = this.line;
    const startCol = this.column;
    this.advance(); // skip /
    this.advance(); // skip *

    let depth = 1;
    while (depth > 0 && this.currentChar()) {
      if (this.currentChar() === '/' && this.peekChar() === '*') {
        this.advance();
        this.advance();
        depth++;
      } else if (this.currentChar() === '*' && this.peekChar() === '/') {
        this.advance();
        this.advance();
        depth--;
      } else {
        this.advance();
      }
    }

    if (depth > 0) {
      this.errors.push({
        line: startLine,
        column: startCol,
        message: 'unterminated block comment'
      });
      return false;
    }
    return true;
  }

  readString() {
    const startLine = this.line;
    const startCol = this.column;
    this.advance(); // skip opening "

    let value = '';
    while (this.currentChar() && this.currentChar() !== '"') {
      if (this.currentChar() === '\n') {
        this.errors.push({
          line: this.line,
          column: this.column,
          message: 'newline in string'
        });
        return null;
      }

      if (this.currentChar() === '\\') {
        const escLine = this.line;
        const escCol = this.column;
        this.advance(); // skip \
        const ch = this.currentChar();

        if (ch === 'n') {
          value += '\n';
          this.advance();
        } else if (ch === 't') {
          value += '\t';
          this.advance();
        } else if (ch === 'r') {
          value += '\r';
          this.advance();
        } else if (ch === '\\') {
          value += '\\';
          this.advance();
        } else if (ch === '"') {
          value += '"';
          this.advance();
        } else if (ch === '0') {
          value += '\0';
          this.advance();
        } else if (ch === 'x') {
          this.advance();
          let hex = '';
          for (let i = 0; i < 2; i++) {
            const hch = this.currentChar();
            if (!/[0-9a-fA-F]/.test(hch)) {
              this.errors.push({
                line: escLine,
                column: escCol,
                message: `invalid escape \\${ch}${this.input.substring(this.pos, this.pos + 2)}`
              });
              return null;
            }
            hex += hch;
            this.advance();
          }
          value += String.fromCharCode(parseInt(hex, 16));
        } else if (ch === 'u') {
          this.advance();
          if (this.currentChar() !== '{') {
            this.errors.push({
              line: escLine,
              column: escCol,
              message: `invalid escape \\u`
            });
            return null;
          }
          this.advance();
          let hex = '';
          while (this.currentChar() && this.currentChar() !== '}') {
            const hch = this.currentChar();
            if (!/[0-9a-fA-F]/.test(hch)) {
              this.errors.push({
                line: escLine,
                column: escCol,
                message: `invalid escape \\u{...}`
              });
              return null;
            }
            hex += hch;
            this.advance();
          }
          if (!hex || hex.length === 0) {
            this.errors.push({
              line: escLine,
              column: escCol,
              message: `invalid escape \\u{}`
            });
            return null;
          }
          const codePoint = parseInt(hex, 16);
          if (codePoint > 0x10FFFF) {
            this.errors.push({
              line: escLine,
              column: escCol,
              message: `invalid escape \\u{${hex}}`
            });
            return null;
          }
          value += String.fromCodePoint(codePoint);
          if (this.currentChar() === '}') {
            this.advance();
          } else {
            this.errors.push({
              line: escLine,
              column: escCol,
              message: `invalid escape \\u{...}`
            });
            return null;
          }
        } else {
          this.errors.push({
            line: escLine,
            column: escCol,
            message: `invalid escape \\${ch || ''}`
          });
          return null;
        }
      } else {
        value += this.currentChar();
        this.advance();
      }
    }

    if (this.currentChar() !== '"') {
      this.errors.push({
        line: startLine,
        column: startCol,
        message: 'unterminated string'
      });
      return null;
    }

    this.advance(); // skip closing "
    return value;
  }

  readRawString() {
    const startLine = this.line;
    const startCol = this.column;
    this.advance(); // skip r
    this.advance(); // skip "

    let value = '';
