{"file_path":"src/limiter.js","content":"/**
 * Main limiter logic that orchestrates policies and events.
 */

import { TokenBucket, SlidingWindow } from './policies.js'

export class Limiter {
  constructor(config) {
    this.policies = new Map() // name -> policy instance
    for (const [name, def] of config.policies) {
      this.policies.set(
        name,
        def.kind === 'bucket'
          ? new TokenBucket(def.capacity, def.refill, def.per)
          : new SlidingWindow(def.limit, def.span)
      )
    }
    // Routes, longest prefix first so the first match wins.
    this.routes = [...config.routes.entries()]
      .map(([prefix, names]) => ({ prefix, names }))
      .sort((a, b) => b.prefix.length - a.prefix.length)
  }

  routeFor(key) {
    for (const route of this.routes) {
      if (key.startsWith(route.prefix)) return route.names
    }
    return null
  }

  processEvents(events) {
    const results = []

    for (const event of events) {
      const names = this.routeFor(event.key)

      // A key no route matches is always allowed.
      if (names === null) {
        results.push({ tick: event.tick, key: event.key, allowed: true })
        continue
      }

      const policies = names.map((name) => ({ name, policy: this.policies.get(name) }))

      // Every policy first advances to the event's tick.
      for (const p of policies) p.policy.advance(event.key, event.tick)

      // Then every one of them is asked, in the order the route wrote them.
      let deniedBy = null
      for (const p of policies) {
        if (!p.policy.allows(event.key, event.tick)) {
          deniedBy = p.name
          break
        }
      }

      if (deniedBy === null) {
        // Only when all allow does each of them record it.
        for (const p of policies) p.policy.record(event.key, event.tick)
        results.push({ tick: event.tick, key: event.key, allowed: true })
      } else {
        // A denied event changes no policy's stored allowance.
        results.push({ tick: event.tick, key: event.key, allowed: false, policy: deniedBy })
      }
    }

    return results
  }
}
"}

