{"file_path":"src/scanner.js","content":"/**
 * The scanner. `scan(text)` turns a source string into a list of tokens, or
 * throws a `ScanError` carrying the position and the reason of the first
 * failure it meets.
 */

export class ScanError extends Error {
  constructor(line, column, reason) {
    super(`${line}:${column}: ${reason}`)
    this.name = 'ScanError'
    this.line = line
    this.column = column
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = ['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']

const isDigit = (c) => c >= '0' && c <= '9'
const isHex = (c) => isDigit(c) || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c >= '0' && c <= '7'
const isLetter = (c) => (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
const isIdentStart = (c) => isLetter(c) || c === '_'
const isIdentPart = (c) => isIdentStart(c) || isDigit(c)

class Scanner {
  constructor(text) {
    this.chars = Array.from(text)
    this.i = 0
    this.line = 1
    this.column = 1
  }

  at(offset = 0) {
    const c = this.chars[this.i + offset]
    return c === undefined ? null : c
  }

  done() {
    return this.i >= this.chars.length
  }

  /** Consumes one code point and moves the position over it. */
  next() {
    const c = this.chars[this.i]
    this.i += 1
    if (c === '\n') {
      this.line += 1
      this.column = 1
    } else if (c === '\t') {
      this.column = Math.floor((this.column - 1) / 4) * 4 + 5
    } else {
      this.column += 1
    }
    return c
  }

  error(line, column, reason) {
    return new ScanError(line, column, reason)
  }

  scan() {
    const tokens = []
    for (;;) {
      this.skipTrivia()
      if (this.done()) return tokens
      tokens.push(this.token())
    }
  }

  skipTrivia() {
    for (;;) {
      const c = this.at()
      if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
        this.next()
        continue
      }
      if (c === '/' && this.at(1) === '/') {
        while (!this.done() && this.at() !== '\n') this.next()
        continue
      }
      if (c === '/' && this.at(1) === '*') {
        this.blockComment()
        continue
      }
      return
    }
  }

  blockComment() {
    const line = this.line
    const column = this.column
    let depth = 0
    for (;;) {
      if (this.done()) throw this.error(line, column, 'unterminated block comment')
      if (this.at() === '/' && this.at(1) === '*') {
        this.next()
        this.next()
        depth += 1
        continue
      }
      if (this.at() === '*' && this.at(1) === '/') {
        this.next()
        this.next()
        depth -= 1
        if (depth === 0) return
        continue
      }
      this.next()
    }
  }

  token() {
    const line = this.line
    const column = this.column
    const c = this.at()

    if (c === 'r' && this.at(1) === '"') return this.rawString(line, column)
    if (isIdentStart(c)) return this.identifier(line, column)
    if (isDigit(c)) return this.number(line, column)
    if (c === '"') return this.string(line, column)

    const two = c + (this.at(1) === null ? '' : this.at(1))
    if (PUNCT2.includes(two)) {
      this.next()
      this.next()
      return { line, column, kind: 'punct', text: two }
    }
    if (PUNCT1.includes(c)) {
      this.next()
      return { line, column, kind: 'punct', text: c }
    }
    throw this.error(line, column, `unexpected character ${c}`)
  }

  identifier(line, column) {
    let text = ''
    while (!this.done() && isIdentPart(this.at())) text += this.next()
    return { line, column, kind: KEYWORDS.has(text) ? 'keyword' : 'ident', text }
  }

  /** Reads a run of digits, where `_` is allowed only between two of them. */
  digitRun(ok) {
    let text = ''
    for (;;) {
      const c = this.at()
      if (c !== null && ok(c)) {
        text += this.next()
        continue
      }
      if (c === '_' && text.length > 0 && this.at(1) !== null && ok(this.at(1))) {
        text += this.next()
        text += this.next()
        continue
      }
      return text
    }
  }

  number(line, column) {
    let text = ''
    const prefix = this.at() === '0' ? this.at(1) : null
    let radix = null
    if (prefix === 'x' || prefix === 'X') radix = isHex
    else if (prefix === 'b' || prefix === 'B') radix = isBin
    else if (prefix === 'o' || prefix === 'O') radix = isOct

    if (radix !== null) {
