{"file_path":"src/parse.js","content":"/**
 * Reading a build graph out of the text on standard input.
 *
 * `parse` returns `{ tasks, deps, order }` where `tasks` maps a name to its
 * cost, `deps` maps a name to the array of names it depends on (each edge
 * once, in first-seen order) and `order` is the task names in declaration
 * order. A failure is reported by throwing a `GraphError`.
 */

export class GraphError extends Error {
  constructor(message, code) {
    super(message)
    this.exitCode = code
  }
}

const NAME = /^[A-Za-z0-9_.-]+$/
const COST = /^[0-9]+$/

/** Names sort by code unit, which is what "ascending name order" means here. */
export function byName(a, b) {
  if (a < b) return -1
  if (a > b) return 1
  return 0
}

/** The lines of the input, without the empty tail a trailing newline leaves. */
export function splitLines(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

export function parse(input) {
  const tasks = new Map()
  const deps = new Map()
  const order = []
  // Every name a dep line uses, in input order, with nothing repeated.
  const used = []

  const lines = splitLines(input)
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const words = line.split(/\s+/)

    if (words[0] === 'task') {
      if (words.length !== 3) {
        throw new GraphError(`error: line ${lineNo}: expected task <name> <cost>`, 2)
      }
      const [, name, cost] = words
      if (!NAME.test(name)) {
        throw new GraphError(`error: line ${lineNo}: invalid task name ${name}`, 2)
      }
      if (!COST.test(cost)) {
        throw new GraphError(`error: line ${lineNo}: cost must be a non-negative integer`, 2)
      }
      if (tasks.has(name)) {
        throw new GraphError(`error: line ${lineNo}: task ${name} is declared twice`, 2)
      }
      tasks.set(name, Number(cost))
      order.push(name)
    } else if (words[0] === 'dep') {
      if (words.length < 3) {
        throw new GraphError(`error: line ${lineNo}: expected dep <name> <dependency>...`, 2)
      }
      for (const name of words.slice(1)) {
        if (!NAME.test(name)) {
          throw new GraphError(`error: line ${lineNo}: invalid task name ${name}`, 2)
        }
        if (!used.includes(name)) used.push(name)
      }
      const name = words[1]
      if (!deps.has(name)) deps.set(name, [])
      const edges = deps.get(name)
      for (const dep of words.slice(2)) {
        if (!edges.includes(dep)) edges.push(dep)
      }
    } else {
      throw new GraphError(`error: line ${lineNo}: unknown directive ${words[0]}`, 2)
    }
  }

  for (const name of used) {
    if (!tasks.has(name)) throw new GraphError(`error: unknown task ${name}`, 2)
  }

  for (const name of tasks.keys()) {
    if (!deps.has(name)) deps.set(name, [])
  }

  return { tasks, deps, order }
}

/**
 * The first cycle a depth-first search finds, starting from each task in
 * ascending name order and walking each task's dependencies in ascending name
 * order, or null when the graph is acyclic. The cycle runs from the task the
 * search re-entered, through the search stack, back to that task.
 */
export function findCycle({ tasks, deps }) {
  const names = [...tasks.keys()].sort(byName)
  const sorted = new Map(names.map((n) => [n, [...deps.get(n)].sort(byName)]))
  const done = new Set()
  const onStack = new Set()
  const stack = []

  function walk(name) {
    onStack.add(name)
    stack.push(name)
    for (const dep of sorted.get(name)) {
      if (onStack.has(dep)) {
        return [...stack.slice(stack.indexOf(dep)), dep]
      }
      if (!done.has(dep)) {
        const cycle = walk(dep)
        if (cycle) return cycle
      }
    }
    stack.pop()
    onStack.delete(name)
    done.add(name)
    return null
  }

  for (const name of names) {
    if (done.has(name)) continue
    const cycle = walk(name)
    if (cycle) return cycle
  }
  return null
}
"}

