{"file_path":"src/uri.js","content":"/**
 * RFC 3986 URI parsing, normalization and reference resolution.
 * Components are `undefined` when absent and `''` when present but empty.
 */

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export class UriError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

function asciiLower(text) {
  let out = ''
  for (let i = 0; i < text.length; i++) {
    const code = text.charCodeAt(i)
    out += code >= 65 && code <= 90 ? String.fromCharCode(code + 32) : text[i]
  }
  return out
}

export function parseUri(uri) {
  let scheme
  let authority
  let path
  let query
  let fragment
  let i = 0

  const delim = uri.search(/[:/?#]/)
  if (delim !== -1 && uri[delim] === ':' && delim > 0) {
    scheme = uri.slice(0, delim)
    i = delim + 1
  }

  if (uri.startsWith('//', i)) {
    i += 2
    const rest = uri.slice(i)
    const end = rest.search(/[/?#]/)
    if (end === -1) {
      authority = rest
      i = uri.length
    } else {
      authority = rest.slice(0, end)
      i += end
    }
  }

  {
    const rest = uri.slice(i)
    const end = rest.search(/[?#]/)
    if (end === -1) {
      path = rest
      i = uri.length
    } else {
      path = rest.slice(0, end)
      i += end
    }
  }

  if (uri[i] === '?') {
    i += 1
    const rest = uri.slice(i)
    const end = rest.indexOf('#')
    if (end === -1) {
      query = rest
      i = uri.length
    } else {
      query = rest.slice(0, end)
      i += end
    }
  }

  if (uri[i] === '#') {
    fragment = uri.slice(i + 1)
  }

  return { scheme, authority, path, query, fragment }
}

export function formatUri(uri) {
  let out = ''
  if (uri.scheme !== undefined) out += uri.scheme + ':'
  if (uri.authority !== undefined) out += '//' + uri.authority
  out += uri.path
  if (uri.query !== undefined) out += '?' + uri.query
  if (uri.fragment !== undefined) out += '#' + uri.fragment
  return out
}

export function parseAuthority(authority) {
  let userinfo
  let rest = authority
  const at = rest.lastIndexOf('@')
  if (at !== -1) {
    userinfo = rest.slice(0, at)
    rest = rest.slice(at + 1)
  }
  const bracket = rest.lastIndexOf(']')
  const colon = rest.indexOf(':', bracket === -1 ? 0 : bracket)
  let host = rest
  let port
  if (colon !== -1) {
    host = rest.slice(0, colon)
    port = rest.slice(colon + 1)
  }
  return { userinfo, host, port }
}

export function formatAuthority({ userinfo, host, port }) {
  let out = ''
  if (userinfo !== undefined) out += userinfo + '@'
  out += host
  if (port !== undefined) out += ':' + port
  return out
}

function isUnreserved(code) {
  return (
    (code >= 0x41 && code <= 0x5a) ||
    (code >= 0x61 && code <= 0x7a) ||
    (code >= 0x30 && code <= 0x39) ||
    code === 0x2d ||
    code === 0x2e ||
    code === 0x5f ||
    code === 0x7e
  )
}

const HEX = /^[0-9A-Fa-f]{2}$/

export function normalizePercents(text, component) {
  if (text === undefined) return undefined
  let out = ''
  for (let i = 0; i < text.length; i++) {
    if (text[i] !== '%') {
      out += text[i]
      continue
    }
    const hex = text.slice(i + 1, i + 3)
    if (hex.length < 2 || !HEX.test(hex)) throw new UriError(component)
    const code = parseInt(hex, 16)
    out += isUnreserved(code) ? String.fromCharCode(code) : '%' + hex.toUpperCase()
    i += 2
  }
  return out
}

export function removeDotSegments(path) {
  let input = path
  let output = ''
  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      output = output.slice(0, Math.max(0, output.lastIndexOf('/')))
    } else if (input === '/..') {
      input = '/'
      output = output.slice(0, Math.max(0, output.lastIndexOf('/')))
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      const start = input[0] === '/' ? 1 : 0
      let next = input.indexOf('/', start)
      if (next === -1) next = input.length
      output += input.slice(0, next)
      input = input.slice(next)
    }
  }
  return output
}

/** Normalize a parsed URI in place-ish; returns a new component object. */
export function normalizeParsed(uri) {
  const out = { ...uri }

  if (out.scheme !== undefined) out.scheme = asciiLower(out.scheme)

  let auth
  if (out.authority !== undefined) auth = parseAuthority(out.authority)

  // Percent-encoding normalization, checked in order:
  // path, userinfo, host, query, fragment.
  out.path = normalizePercents(out.path, 'path')
  if (auth !== undefined) {
    auth.userinfo = normalizePercents(auth.userinfo, 'userinfo')
    auth.host = normalizePercents(auth.host, 'host')
  }
  out.query = normalizePercents(out.query, 'query')
  out.fragment = normalizePercents(out.fragment, 'fragment')

  if (auth !== undefined) {
    auth.host = asciiLower(auth.host)
    if (auth.port !== undefined) {
      const def = out.scheme === undefined ? undefined : DEFAULT_PORTS[out.scheme]
      if (auth.port === '' || (def !== undefined && auth.port === def)) auth.port = undefined
    }
    out.authority = formatAuthority(auth)
  }

  out.path = removeDotSegments(out.path)
  if (out.authority !== undefined && out.path === '') out.path = '/'

  return out
}

export function normalize(reference) {
  return formatUri(normalizeParsed(parseUri(reference)))
}

function merge(base, refPath) {
  if (base.authority !== undefined && base.path === '') return '/' + refPath
  const slash = base.path.lastIndexOf('/')
  if (slash === -1) return refPath
  return base.path.slice(0, slash + 1) + refPath
}

export function resolve(baseString, refString) {
  const base = parseUri(baseString)
  const ref = parseUri(refString)
  const target = {}

  if (ref.scheme !== undefined) {
    target.scheme = ref.scheme
    target.authority = ref.authority
    target.path = removeDotSegments(ref.path)
    target.query = ref.query
  } else if (ref.authority !== undefined) {
    target.scheme = base.scheme
    target.authority = ref.authority
    target.path = removeDotSegments(ref.path)
    target.query = ref.query
  } else {
    target.scheme = base.scheme
    target.authority = base.authority
    if (ref.path === '') {
      target.path = base.path
      target.query = ref.query !== undefined ? ref.query : base.query
    } else {
      target.path = removeDotSegments(
        ref.path.startsWith('/') ? ref.path : merge(base, ref.path)
      )
      target.query = ref.query
    }
  }
  target.fragment = ref.fragment

  return formatUri(normalizeParsed(target))
}
"}

