{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { readFileSync } from 'node:fs'
import { normalize, parseUri, resolve, UriError } from './uri.js'

function fail(message) {
  process.stderr.write('error: ' + message + '\n')
  process.exit(2)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function splitRecords(input) {
  if (input === '') return []
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  return lines
}

function main() {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || (argv[0] !== 'normalize' && argv[0] !== 'resolve')) {
    fail('usage: cli.js normalize|resolve')
  }
  const mode = argv[0]
  const records = splitRecords(readStdin())
  const out = []

  for (let i = 0; i < records.length; i++) {
    const record = records[i]
    const n = i + 1
    try {
      if (mode === 'normalize') {
        out.push(normalize(record))
      } else {
        const space = record.indexOf(' ')
        if (space === -1) fail(`line ${n}: expected a base and a reference`)
        const base = record.slice(0, space)
        const reference = record.slice(space + 1)
        if (parseUri(base).scheme === undefined) fail(`line ${n}: the base has no scheme`)
        out.push(resolve(base, reference))
      }
    } catch (error) {
      if (error instanceof UriError) fail(`line ${n}: ${error.message}`)
      throw error
    }
  }

  if (out.length > 0) process.stdout.write(out.join('\n') + '\n')
}

main()
"}

